update public.government_schemes
set source_name='Prime Minister’s Youth Programme / Press Information Department — Government of Pakistan',
source_document_url='https://pid.gov.pk/site/press_detail/34717',
benefit_details='The official PMYB&ALS portal currently displays three tiers: up to PKR 500,000 at 0% markup; above PKR 500,000 up to PKR 1.5 million at 5%; and above PKR 1.5 million up to PKR 7.5 million at 7%. The Press Information Department announced on 10 November 2026 that a new Tier 4 has been approved for loans above PKR 7.5 million up to PKR 25 million at 8% markup for up to eight years. The portal page reviewed still displays the older three tiers, so confirm that the live form and participating bank have implemented Tier 4 before applying. This is repayable financing, not a grant.',
eligibility_text='The PMYB&ALS information portal and PID Tier 4 release list Pakistani residents aged 21–45, with an 18-year lower age limit for IT / e-commerce businesses. Radio Pakistan reported an 8 November 2026 Government direction to reduce the minimum age to 18 for all applicants. These official pages therefore differ on the age change; applicants aged 18–20 outside IT / e-commerce should confirm the currently implemented rule with the PMYP Digital Youth Hub / participating bank before applying. Government employees and non-residents should review the current official exclusions.',
application_steps='The PID announcement directs applicants to the Prime Minister’s Digital Youth Hub at pmyp.gov.pk or the PMYP mobile app. The separate PMYB&ALS information portal reviewed still displays the original three tiers; confirm that the Tier 4 option, current age rules and application form are active through the official hub / participating bank before applying. Radio Pakistan reported the Government direction to lower the minimum age to 18 for all applicants, while the PID Tier 4 release and older portal still state 21–45 (18 for IT / e-commerce). No agent or recommendation is required; banks decide applications on merit. Never upload identity or supporting documents to Hello Sadiqabad or share them in chat.',
fees_and_repayment='Portal tiers: 0% markup up to PKR 500,000; 5% above PKR 500,000 up to PKR 1.5 million; 7% above PKR 1.5 million up to PKR 7.5 million. PID states the new Tier 4 is above PKR 7.5 million up to PKR 25 million at 8% markup for up to eight years. Confirm the current form, fees, security, tenor and bank conditions before applying.',
verified_at=now(),next_review_at=now()+interval '7 days',updated_at=now()
where slug='prime-minister-youth-business-agriculture-loan';